import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"第一阶段 MVP 验收","description":"15 个跨行业真实任务的结果、证据与未完成边界。","frontmatter":{"title":"第一阶段 MVP 验收","description":"15 个跨行业真实任务的结果、证据与未完成边界。","outline":[2,3]},"headers":[],"relativePath":"delivery/mvp.md","filePath":"delivery/mvp.md","lastUpdated":null}'),a={name:"delivery/mvp.md"};function r(s,t,i,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="第一阶段-mvp-验收" tabindex="-1">第一阶段 MVP 验收 <a class="header-anchor" href="#第一阶段-mvp-验收" aria-label="Permalink to &quot;第一阶段 MVP 验收&quot;">​</a></h1><p class="lead">第一阶段的出口不是“代码写完”，而是用 15 个跨行业真实任务证明同一条任务链路可以执行、持久化、审批、产出、失败恢复和备份。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>结果</th></tr></thead><tbody><tr><td>验收日期</td><td>2026-11-05</td></tr><tr><td>任务总数</td><td>15</td></tr><tr><td>通过</td><td>13（T01–T06、T09–T15）</td></tr><tr><td>产物通过但等待外部批准</td><td>1（T08）</td></tr><tr><td>未通过</td><td>1（T07）</td></tr><tr><td>硬门槛</td><td>至少 10/15 通过；已超过</td></tr></tbody></table><p>T07 和 T08 没有用于凑数。T07 以 <code>recoverable</code> 结束并保留失败证据；T08 的 GitHub 评论审批仍是 <code>pending</code>，没有任何外部副作用。</p><h2 id="逐项结果" tabindex="-1">逐项结果 <a class="header-anchor" href="#逐项结果" aria-label="Permalink to &quot;逐项结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>结果</th><th>已保存的证据</th><th>验收说明</th></tr></thead><tbody><tr><td>T01</td><td>通过</td><td><code>runs/T01/meeting-notes.md</code>、<code>run-manifest.json</code></td><td>会议转写转行动纪要，保留行动项、负责人、日期、待确认项和来源索引</td></tr><tr><td>T02</td><td>通过</td><td><code>runs/T02/clause-checklist.md</code>、<code>run-manifest.json</code></td><td>合同条款、义务、页码、缺失附件和金额可核对，未补造缺失信息</td></tr><tr><td>T03</td><td>通过</td><td><code>runs/T03/executive-summary.md</code>、<code>run-manifest.json</code></td><td>多报告合并时保留冲突和来源，不把矛盾结论强行统一</td></tr><tr><td>T04</td><td>通过</td><td><code>runs/T04/pages/</code>、<code>manifest.json</code>、<code>verification.md</code>、<code>run-manifest.json</code></td><td>3 个 URL 均有状态、最终 URL、抓取时间、HTTP 状态和 SHA-256；WCAG 页面访问失败被如实保留</td></tr><tr><td>T05</td><td>通过</td><td><code>runs/T05/competitor-comparison.md</code>、<code>run-manifest.json</code></td><td>竞品价格和功能有来源，未公开项标记未知而非推测</td></tr><tr><td>T06</td><td>通过</td><td><code>runs/T06/policy-update-digest.md</code>、<code>run-manifest.json</code></td><td>政策更新只使用官方来源，日期和变更类型可追溯</td></tr><tr><td>T07</td><td><strong>未通过</strong></td><td><code>runs/T07/report.md</code>、<code>pr-preview.json</code>、<code>run-manifest.json</code></td><td>交付校验拦截：<code>backend/tests/unit/test_health_no_secrets.py</code> 未提交；未推送分支、未创建 PR</td></tr><tr><td>T08</td><td>产物通过，<strong>等待用户批准</strong></td><td><code>runs/T08/pr-review.md</code>、<code>run-manifest.json</code></td><td>固定 PR #15 head <code>c007c4ed55345682689ac50bbafb090c5934c31a</code>，生成 13 KB 分级评审；评论审批状态 <code>pending</code>，<code>effectId</code> 为 <code>null</code></td></tr><tr><td>T09</td><td>通过</td><td><code>runs/T09/bug-reproduction.md</code>、<code>pytest-output.txt</code>、<code>pytest-focused.txt</code>、退出码与路由证据</td><td>复现 PR #14 的 8 个后端失败，保留环境差异、临时目录问题和未验证项</td></tr><tr><td>T10</td><td>通过</td><td><code>runs/T10/cleaned-sales.csv</code>、<code>exceptions.csv</code>、<code>change-log.md</code>、<code>summary.md</code></td><td>20 行销售数据清洗，重复、缺失和异常均可追溯，原文件未修改</td></tr><tr><td>T11</td><td>通过</td><td><code>runs/T11/expense-reconciliation.md</code>、<code>run-manifest.json</code></td><td>7 行逐笔匹配，2640.00 合计复核，异常完整</td></tr><tr><td>T12</td><td>通过</td><td><code>runs/T12/triage.csv</code>、<code>reply-drafts.md</code>、<code>escalations.md</code>、<code>kb-draft.md</code></td><td>8 个工单完成分类、脱敏、升级和回复草稿；未自动发送</td></tr><tr><td>T13</td><td>通过</td><td><code>runs/T13/job-description.md</code>、<code>interview-kit.md</code></td><td>JD 无歧视项；面试工具包和合规自查完整</td></tr><tr><td>T14</td><td>通过</td><td><code>runs/T14/lesson-plan.md</code>、<code>quiz.md</code>、<code>answer-key.md</code></td><td>课程、测验和答案键一致，覆盖目标与难度分层</td></tr><tr><td>T15</td><td>通过</td><td><code>runs/T15/campaign-brief.md</code>、<code>asset-checklist.md</code></td><td>营销主张有输入依据，三渠道素材和审批状态完整；未发布、未投放</td></tr></tbody></table><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to &quot;运行环境&quot;">​</a></h2><ul><li>操作系统：Windows，PowerShell。</li><li>Node.js：<code>v26.11.1</code>；npm：<code>11.20.0</code>。</li><li>控制面：Fastify + TypeScript；前端：React + Vite。</li><li>执行器：Codex 原生适配；实际配置为 <code>OpenDesign / deepseek-v4.1-flash</code>。</li><li>认证来源：<code>provider-env</code>，密钥由启动 Hearth 的终端环境提供，不写入浏览器。</li><li>健康检查：<code>GET /api/health</code> 返回 <code>canRun: true</code>、<code>authSource: &quot;provider-env&quot;</code>、<code>issues: []</code>。</li></ul><p>因此不需要先执行 <code>codex login</code>。只要 <code>~/.codex/config.toml</code> 配置了 <code>model_provider</code> 和对应的 <code>env_key</code>，并且启动 Hearth 的终端存在该变量，Codex 就能作为执行器运行。</p><h2 id="g1–g9-验收基线" tabindex="-1">G1–G9 验收基线 <a class="header-anchor" href="#g1–g9-验收基线" aria-label="Permalink to &quot;G1–G9 验收基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基线</th><th>证据</th></tr></thead><tbody><tr><td>G1 输入范围明确</td><td>任务模板和任务记录包含目标、输入路径/URL、输出目录；运行清单记录输入来源和 SHA-256</td></tr><tr><td>G2 状态可见</td><td>状态机覆盖 <code>queued</code>、<code>running</code>、<code>waiting_input</code>、<code>waiting_approval</code>、<code>completed</code>、<code>failed</code>、<code>recoverable</code>、<code>cancelled</code></td></tr><tr><td>G3 结果持久</td><td>任务、运行、审批、效果、事件和产物索引写入 <code>.hearth/hearth.sqlite</code>，服务重启后可查询</td></tr><tr><td>G4 产物可追溯</td><td>每个 <code>run-manifest.json</code> 记录任务/运行 ID、输入摘要、执行器、生成时间和产物 SHA-256</td></tr><tr><td>G5 外部动作受控</td><td>GitHub 推送、创建 PR 和评论先生成审批预览；T08 审批尚未执行，无效果记录</td></tr><tr><td>G6 不伪造</td><td>T04 访问挑战、T08 缺失 CI 日志、T09 宿主临时目录问题均标记未知或失败</td></tr><tr><td>G7 失败可恢复</td><td>T07 以 <code>recoverable</code> 结束，显示具体未提交文件并保留工作区</td></tr><tr><td>G8 权限最小化</td><td>服务只接受本机回环地址，阻止跨站写请求；外部写入需要绑定参数指纹的一次性审批</td></tr><tr><td>G9 用户可核对</td><td>待办、任务详情、审批预览、产物预览和应用内时间线可直接查看</td></tr></tbody></table><h2 id="自动校验" tabindex="-1">自动校验 <a class="header-anchor" href="#自动校验" aria-label="Permalink to &quot;自动校验&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run typecheck</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run build </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w @hearth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">web</span></span></code></pre></div><p>验收时 <code>npm test</code> 通过 51 项测试；TypeScript 类型检查通过；Web 生产构建通过。2026-11-06 之后测试扩展到 40 个测试文件、199 个测试，当前基线以<a href="/hearth-os/delivery/acceptance.html">验收与证据</a>为准。</p><h2 id="这次验收没有证明什么" tabindex="-1">这次验收没有证明什么 <a class="header-anchor" href="#这次验收没有证明什么" aria-label="Permalink to &quot;这次验收没有证明什么&quot;">​</a></h2><ul><li>没有证明邮件、日历、真实发送或桌面高风险动作可用。</li><li>没有证明手机入口、主动服务打扰控制或多设备切换可用。</li><li>没有证明数周连续运行、资源漂移或版本升级回退可靠。</li><li>没有把 T07 的失败或 T08 的等待批准写成成功。</li></ul><p>逐项原始证据见仓库 <code>eval/phase-1-acceptance.md</code> 与 <code>eval/runs/</code>。</p>`,18)])])}const m=d(a,[["render",r]]);export{u as __pageData,m as default};
